function applySmartMix(){if(!engine){getEngine().then(()=>applySmartMix()).catch(()=>toast('No se pudo iniciar el motor de audio'));return}const targets=[-9,-12,-17,-16,-18,-14,-17,-15],cutsHz=[28,105,420,280,620,120,650,150],tonesHz=[15000,12500,12500,11000,14500,9500,11500,15500];state.smartEQ=true;for(let i=0;i<8;i++){const name=KIT[state.genre][i],buffer=engine.samples[name]||engine.samples[name+'_alt'];let peak=0;if(buffer){for(let ch=0;ch<buffer.numberOfChannels;ch++){const a=buffer.getChannelData(ch);for(let n=0;n<a.length;n++)peak=Math.max(peak,Math.abs(a[n]))}}const target=Math.pow(10,targets[i]/20),trim=clamp(target/Math.max(peak,.001),.2,1.4);state.smartTrim[i]=trim;state.cuts[i]=clamp(Math.log(cutsHz[i]/20)/Math.log(22)*100,0,100);state.tones[i]=clamp(Math.log(tonesHz[i]/700)/Math.log(27)*100,0,100);engine.setSmartTrim(i,trim);engine.setChannelEQ(i)}engine.setMusicEQ();$('smartEqToggle').checked=true;$('smartMixStatus').textContent='Smart Mix aplicado: trims por pico de muestra, EQ correctiva por rol en batería y buses musicales, compresión suave por canal y protección de picos. Faders manuales conservados.';renderMixer();renderStudioExtras();renderMixCoach();save();toast('Smart Mix aplicado · headroom por canal')}
function renderMixCoach(){const p=state.patterns?.[state.genre]?.[state.scene]||[],active=TRACKS.map((t,i)=>({name:t[1],hits:(p[i]||[]).filter(Boolean).length,index:i})).filter(x=>x.hits>0&&!state.mutes[x.index]);const names=active.map(x=>x.name);const messages=[];if(names.includes('KICK')&&state.bass)messages.push('Kick y subgrave activos: el auto-mix reserva espacio por debajo de 120 Hz y el ducking evita que se acumulen.');if(names.includes('CLOSED HAT')&&names.includes('SHAKER'))messages.push('Hay dos capas de agudos: controla el shaker o baja su fader si la mezcla pierde definición.');if(names.includes('CLAP / SNARE')&&names.includes('RIM / CLAVE'))messages.push('Caja y rim comparten zona de ataque: el paneo y la EQ ayudan a separarlos.');if(state.live?.arpOn&&state.chords)messages.push('Acordes y arpegio están activos: prueba abrir el arpegio en estéreo y mantener los acordes más centrados.');if(state.live?.leadOn&&state.chords)messages.push('Lead y acordes ocupan medios: cambia la octava del lead o reduce su presencia para evitar enmascaramiento.');if(state.smartEQ)messages.push('EQ inteligente y protección dinámica activos en ocho canales de batería y cuatro buses musicales.');else messages.push('EQ inteligente desactivado: los filtros manuales siguen disponibles.');if(!active.length)messages.push('La escena no tiene golpes activos; selecciona una escena o activa pasos para analizar el balance.');const msg=messages.join(' ');if($('mixCoachText'))$('mixCoachText').textContent=msg;if($('liveCoachText'))$('liveCoachText').textContent=msg}
