function midiFile(bars=state.renderBars){const ppq=480,events=[{tick:0,sort:0,data:[0xff,0x51,3,...be32(Math.round(60000000/state.bpm)).slice(1)]},{tick:0,sort:0,data:[0xff,0x58,4,4,2,24,8]}];
 for(let bar=0;bar<bars;bar++){const deg=state.progression[bar%4];if(state.chords&&state.live?.layers?.chords!==false)voicedChord(deg,bar).forEach((n,i)=>{const human=(unitNoise(bar,i,7,2)-.5)*.016*(state.humanize/100),strum=(state.strum/100)*(['nylonGuitar','steelGuitar'].includes(state.patch)?.018:.045)*i;const drift=Math.max(0,Math.round((.016+human+strum)*state.bpm/60*ppq));const velocity=Math.max(1,Math.round(83-i*4+(unitNoise(bar,i,4,2)-.5)*12*(state.humanize/100)));
 events.push({tick:bar*4*ppq+drift,sort:2,data:[0x90,n,velocity]});events.push({tick:(bar+1)*4*ppq-85+drift,sort:1,data:[0x80,n,0]})});
 if(state.bass&&state.live?.layers?.bass!==false)for(const step of [0,6,10,14]){const midi=36+state.root+MODES[state.mode][deg]+(step===14?12:0),when=bar*ppq*4+step*ppq/4;events.push({tick:when,sort:2,data:[0x91,midi,95]});events.push({tick:when+ppq/5,sort:1,data:[0x81,midi,0]})}
 if(window.AURALIS_LIVE?.midiEvents)window.AURALIS_LIVE.midiEvents(events,bar,ppq);
 const p=state.patterns[state.genre][state.arrangement[bar%8]];for(let r=0;r<8;r++)if(state.live?.layers?.drums!==false&&!state.mutes[r])for(let s=0;s<16;s++){const vel=p[r][s];if(vel){const h=humanHit(bar,r,s,vel),swing=(s%2?ppq/4*(state.swing/100)*.58:0),jitter=h.offset*state.bpm/60*ppq;const tick=Math.max(0,Math.round(bar*ppq*4+s*ppq/4+swing+jitter));events.push({tick,sort:2,data:[0x99,TRACKS[r][3],h.velocity]});events.push({tick:tick+Math.round(ppq/11),sort:1,data:[0x89,TRACKS[r][3],0]})}}}
 events.sort((a,b)=>a.tick-b.tick||a.sort-b.sort);let track=[],cursor=0;for(const e of events){track.push(...varlen(e.tick-cursor),...e.data);cursor=e.tick}track.push(...varlen(Math.max(0,bars*ppq*4-cursor)),0xff,0x2f,0);return new Uint8Array([77,84,104,100,0,0,0,6,0,0,0,1,...be16(ppq),77,84,114,107,...be32(track.length),...track])}
