 const bars=state.renderBars,rate=48000,total=Math.ceil((barSec()*bars+2)*rate),offline=new Offline(2,total,rate);progress(13,'Descodificando biblioteca PCM24');
 const samples=engine?.samples||await decodeSoundbank(offline);const e=new AudioEngine(offline,samples);const notes=state.progression.flatMap((d,i)=>voicedChord(d,i));await e.prepareInstrument(state.patch,notes);await window.AURALIS_LIVE?.prepare(e);e.setFilter(state.filter);e.setEcho(state.echo);e.masterMix.gain.value=.76;if(state.renderPart==='drums'){e.drumsCross.gain.cancelScheduledValues(0);e.musicCross.gain.cancelScheduledValues(0);e.drumsCross.gain.setValueAtTime(1,0);e.musicCross.gain.setValueAtTime(0,0);}else if(state.renderPart==='music'){e.drumsCross.gain.cancelScheduledValues(0);e.musicCross.gain.cancelScheduledValues(0);e.drumsCross.gain.setValueAtTime(0,0);e.musicCross.gain.setValueAtTime(1,0);}else{e.drumsCross.gain.cancelScheduledValues(0);e.musicCross.gain.cancelScheduledValues(0);e.drumsCross.gain.setValueAtTime(Math.SQRT1_2,0);e.musicCross.gain.setValueAtTime(Math.SQRT1_2,0);}
 const barDuration=barSec(),start=.10;progress(25,'Construyendo '+bars+' compases y efectos');for(let bar=0;bar<bars;bar++){insertAutoFx(e,bar,start+bar*barDuration);for(let s=0;s<16;s++)playStep(e,bar*16+s,start+bar*barDuration+s*barDuration/16)}
 if(state.renderPart==='music')e.drumsBus.gain.value=0;if(state.renderPart==='drums')e.musicBus.gain.value=0;
 progress(42,'Procesando mezcla / compresión de bus');await new Promise(resolve=>setTimeout(resolve,40));const rendered=await offline.startRendering();progress(79,'Cuantización 24 bits y dither');await new Promise(resolve=>setTimeout(resolve,30));const wav=pcm24(rendered);progress(92,'Guardando archivo WAV');const fn='Auralis_'+state.genre+'_'+state.bpm+'BPM_'+bars+'bars_'+state.renderPart+'_48k_24bit.wav';await downloadBlob(fn,new Blob([wav.data],{type:'audio/wav'}));progress(100,'Exportación completada · pico '+wav.peakDb.toFixed(1)+' dBFS');toast('WAV 48 kHz / 24-bit exportado');
