async function exportMIDI(){try{await downloadBlob('Auralis_'+state.genre+'_'+state.bpm+'bpm.mid',new Blob([midiFile()],{type:'audio/midi'}));toast('MIDI exportado · notas y ritmos')}catch(err){console.error(err);toast('Error al guardar MIDI')}}
async function exportJSON(){try{await downloadBlob('Auralis_Studio_2_Sesion.json',new Blob([JSON.stringify({format:'auralis-studio-v2',created:new Date().toISOString(),state},null,2)],{type:'application/json'}));toast('Sesión exportada')}catch(err){console.error(err);toast('Error al guardar sesión')}}
function importJSON(file){if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const obj=JSON.parse(reader.result);if(obj.format!=='auralis-studio-v2'||!obj.state||!obj.state.patterns)throw Error('No es un proyecto 2.0');stop();localStorage.setItem('auralis-studio-v2',JSON.stringify(obj.state));state=initialState();load();renderAll();toast('Sesión cargada');}catch(err){toast('Archivo no válido para AURALIS 2.0')}};reader.readAsText(file)}
function drawWave(id,t,kind){const c=$(id);if(!c)return;const box=c.getBoundingClientRect(),w=box.width,h=box.height;if(w<10||h<10)return;const dpr=Math.min(2,window.devicePixelRatio||1);if(c.width!==Math.round(w*dpr)||c.height!==Math.round(h*dpr)){c.width=Math.round(w*dpr);c.height=Math.round(h*dpr)}const g=c.getContext('2d');g.setTransform(dpr,0,0,dpr,0,0);g.clearRect(0,0,w,h);
 let accent=kind==='dj'?'#c9b6ff':state.genre==='afro'?'#feb48c':state.genre==='house'?'#a8c5ff':'#dab8ff';g.lineWidth=kind==='dj'?1.2:1.4;
 const active=playing?1:.38;if(kind==='hero'){g.strokeStyle='#ffffff25';for(let x=0;x<w;x+=w/25){g.beginPath();g.moveTo(x,0);g.lineTo(x,h);g.stroke()}g.strokeStyle=accent;for(let band=0;band<3;band++){g.beginPath();g.globalAlpha=.9-band*.24;for(let x=0;x<=w;x+=2){let phase=x/w*Math.PI*10;let amp=(Math.sin(phase+band*1.7+t*(playing?.003:.0003))*.55+Math.sin(phase*2.9+t*.0018+band)*.2)*((1-Math.abs(x/w-.5))*h*.35)*active;let y=h*.5+amp+(band-1)*8;if(x===0)g.moveTo(x,y);else g.lineTo(x,y)}g.stroke()}g.globalAlpha=1;}
 if(kind==='synth'||kind==='dj'){for(let band=0;band<2;band++){g.strokeStyle=band===0?accent:'#d2fe72';g.globalAlpha=band===0?.85:.4;g.beginPath();for(let x=0;x<=w;x+=2){let a=(Math.sin(x*.049+t*.0021+band*2)+Math.sin(x*.12+t*.0015+band)*.38)*h*.16*active;let y=h*.5+a;if(x===0)g.moveTo(x,y);else g.lineTo(x,y)}g.stroke()}g.globalAlpha=1;}}
function updateMeter(){const v=$('meterReadout'),bars=[...$('vuBars').children];let peak=0;if(engine){const a=new Uint8Array(engine.analyser.fftSize);engine.analyser.getByteTimeDomainData(a);for(let i=0;i<a.length;i++)peak=Math.max(peak,Math.abs((a[i]-128)/128));energy=energy*.75+peak*.25;}else energy*=.86;v.textContent=energy>.002?(20*Math.log10(energy)).toFixed(1)+' dB':'−∞ dB';const n=clamp(Math.round(energy*18),0,bars.length);bars.forEach((x,i)=>{x.classList.toggle('on',i<n);x.classList.toggle('warn',i>9)});}
function animate(time){if(time-stamp>38){stamp=time;drawWave('heroWave',time,'hero');if($('view-harmony').classList.contains('active'))drawWave('synthWave',time,'synth');if($('view-dj').classList.contains('active'))drawWave('djWave',time,'dj');if($('view-studio').classList.contains('active'))updateMeter();if($('view-mixer').classList.contains('active'))updateStereoMeters();}animRaf=requestAnimationFrame(animate)}
