 $('playButton').addEventListener('click',togglePlay);$('stopButton').addEventListener('click',()=>stop(true));$('tempoMinus').addEventListener('click',()=>{state.bpm=clamp(state.bpm-1,65,180);renderGenre();updateEstimate();save()});$('tempoPlus').addEventListener('click',()=>{state.bpm=clamp(state.bpm+1,65,180);renderGenre();updateEstimate();save()});
 patchControls();wireFX();wireMixer();window.AURALIS_LIVE?.wire();$('renderBars').addEventListener('change',ev=>{state.renderBars=Number(ev.target.value);updateEstimate();save()});$('renderPart').addEventListener('change',ev=>{state.renderPart=ev.target.value;save()});$('renderWav').addEventListener('click',exportAudio);$('exportMidi').addEventListener('click',exportMIDI);$('exportSession').addEventListener('click',exportJSON);$('importSession').addEventListener('click',()=>$('importFile').click());$('importFile').addEventListener('change',ev=>{importJSON(ev.target.files?.[0]);ev.target.value=''});
