window.AURALIS_API={getState:()=>state,getEngine,context:()=>ctx,isPlaying:()=>playing,save,toast,triggerFX,getChordNotes:degree=>voicedChord(degree,barAt),getChordName:degree=>chordName(degree),noteName:note=>NOTE_NAMES[((note%12)+12)%12]+(Math.floor(note/12)-1),scaleSemitone:degree=>MODES[state.mode][((degree%7)+7)%7],scaleName:degree=>{const sc=MODES[state.mode],d=((degree%7)+7)%7,root=(state.root+sc[d])%12;return NOTE_NAMES[root]+(degree>=7?"′":"")},getScaleNotes:(octave=3,octaves=2)=>{const sc=MODES[state.mode],out=[];for(let o=0;o<octaves;o++)for(let d=0;d<7;d++)out.push(12*(octave+1)+state.root+sc[d]+12*o);return out},prepareInstrument:(patch,notes)=>getEngine().then(e=>e.prepareInstrument(patch,notes)),playNote:async(note,velocity=.75,hold=.6,patch=state.patch,destination=null,pan=0)=>{const e=await getEngine();await e.prepareInstrument(patch,[note]);return e.voice(note,ctx.currentTime+.012,hold,velocity,patch,pan,destination||e.musicChords)},playChord:async(degree)=>{const e=await getEngine(),notes=voicedChord(degree,barAt);await e.prepareInstrument(state.patch,notes);const strumStep=['nylonGuitar','steelGuitar'].includes(state.patch)?.018:.035;notes.forEach((n,i)=>e.voice(n,ctx.currentTime+.018+(state.strum/100)*strumStep*i,.9,.78,state.patch,(i-(notes.length-1)/2)*.11));return notes},playDrum:async(index,velocity=110)=>{const e=await getEngine();return e.drum(index,ctx.currentTime+.008,velocity)},setPatch:patch=>{state.patch=patch;state.live.arpPatch=patch;renderHarmony();window.AURALIS_LIVE?.render();save();if(engine){const notes=state.progression.flatMap((d,i)=>voicedChord(d,i));engine.prepareInstrument(patch,notes).catch(err=>console.warn(err))}},setFilter:value=>{state.filter=clamp(Number(value),0,100);if(engine)engine.setFilter(state.filter);renderFX();save()},setEcho:value=>{state.echo=clamp(Number(value),0,75);if(engine)engine.setEcho(state.echo);renderFX();save()},setSpace:value=>{state.space=clamp(Number(value),0,100);if(engine)engine.setSpace(state.space);save()},setMaster:value=>{state.masterVolume=clamp(Number(value),0,100);if(engine)engine.setMasterVolume(state.masterVolume);save()},setStereoWidth:value=>{state.stereoWidth=clamp(Number(value),0,150);if(engine)engine.setStereoWidth(state.stereoWidth);save()},setMusicLevel:(layer,value)=>{state.live.levels[layer]=clamp(Number(value),0,100);if(engine)engine.setMusicLevel(layer,state.live.levels[layer]);save()},setDelayParam:(key,value)=>{if(!['delayMode','delayDivision','delayFeedback','delayTone'].includes(key))return;state[key]=typeof value==='number'?clamp(value,0,100):value;if(engine)engine.setEchoParams();save()},setTempo:value=>{state.bpm=clamp(Number(value),65,180);renderGenre();updateEstimate();window.AURALIS_LIVE?.render();if(engine)engine.setEchoParams();save()},setScene:scene=>{if(!'ABCD'.includes(scene))return;state.scene=scene;playedScene=scene;if(playing)state.arrangement[Math.floor(nextStepIndex/16)%8]=scene;renderGenre();renderGrid();renderArrangement();window.AURALIS_LIVE?.render();save()},preloadLibrary:async(onProgress)=>{const e=await getEngine();return e.preloadInstrumentLibrary(onProgress)},refreshCoach:renderMixCoach,renderHarmony,renderGenre,renderGrid,renderArrangement};
